-- données extraites du jeu web (habitants, missions, maisons)
return {npcs={{k="maman",who="Miraaï, ta maman",x=155,y=224,src="assets/npc3/maman.png",mw=225,mh=255,head=5,feet=255,cx=111,sc=0.17024,id="rose",need={coconut=4},title="4 noix de coco et un gâteau pour Maman",start={"Myah, ma chérie ! Bientôt, c'est la fête du Cygne. Chaque année, on prépare un grand repas pour dire : « Reviens, Gaïkin ! »","Peux-tu me rapporter 4 noix de coco pour la boisson de la fête ? Prends ton panier (panier) et cherche les cocotiers, près de la maison rose et du bassin !","Et pour la table de la fête, prépare un Maïmaïa , le gâteau de maïs à la mangue ! Cueille 2 mangues près du musée. Pour la farine de maïs, le sucre de canne, les œufs et les épices, va voir Kykah à son épicerie : elle échange contre du maïs et de la canne à sucre du potager, ou des coquillages. Ensuite, cuisine-le à la maison !","Avant de partir, Gaïkin m'a confié un coffre avec une de ses plumes. Je ne dois la donner qu'à quelqu'un de confiance… et pour moi, c'est toi !"},remind={"Pour la fête, il me faut 4 noix de coco et un Maïmaïa. Les mangues sont près du musée, et on cuisine à la maison !"},done={"Oh merci ma puce ! Ces noix de coco sont parfaites, et ce gâteau sent si bon ! Je le garde pour la table de la fête.","Ta grand-mère m'a confié cette plume il y a longtemps. Je l'ai gardée cachée pour que les pirates ne la trouvent pas. Maintenant, c'est toi qui en prendras soin. Mon coffre est caché dans le buisson qui scintille devant la maison, à gauche de la porte. La plume est pour toi !"},final=false,tool="basket",kid=false},{k="frere",who="Nijan, ton petit frère",x=363,y=393,src="assets/npc3/frere.png",mw=257,mh=252,head=1,feet=251,cx=129,sc=0.10336000000000001,id="bleu",need={butterfly=3},title="3 papillons pour Nijan",start={"Myah ! Myah ! Tu sais quoi ? Il y a de moins en moins de papillons…","Avant, il y en avait plein autour des fleurs du lac. Je veux les observer de près pour mon carnet ! Tu peux m'en attraper 3 avec ton filet (filet) ? Je veux les regarder de près ! Avance doucement : ils se posent sur les fleurs.","J'ai un coffre secret avec une plume de Gaïkin. Je te la donne si tu m'aides ! Promis !"},remind={"Il m'en faut encore, des papillons ! Approche-toi doucement avec ton filet !"},done={"Waaaah ! Ils sont trop beaux ! Merci Myah, tu es la meilleure grande sœur !","Les papillons aiment les fleurs du lac. Quand l'eau était propre, il y en avait partout ! Ma plume, je l'ai cachée dans ma boîte à trésors.","Mon coffre est caché à l'étage du musée, en haut de l'échelle Va le chercher !"},final=false,tool="net",kid=false},{k="soigneuse",who="Professeur Lulia",x=413,y=304,src="assets/npc3/soigneuse.png",mw=236,mh=253,head=2,feet=252,cx=126,sc=0.17024,id="soleil",need={flower=5},title="5 fleurs pour Lulia",start={"Bonjour Myah ! Je fais une expérience : je note chaque semaine comment poussent les fleurs de l'île, et certaines fanent bien trop vite.","Peux-tu cueillir 5 jolies fleurs avec ton panier (panier) ? Je vais les soigner.","Gaïkin m'a laissé une plume dans mon coffre. Il m'a dit : « Donne-la à quelqu'un en qui tu as confiance. » Je crois que c'est toi !"},remind={"Encore quelques fleurs , s'il te plaît ! Elles poussent dans les petits jardins."},done={"Quel beau bouquet !","J'ai comparé les fleurs arrosées avec l'eau du lac et celles arrosées avec l'eau de pluie : ce sont les premières qui fanent. Avec ta plume, l'eau du lac redeviendra bonne pour elles.","Mon coffre est caché dans le buisson qui scintille devant le poste de soin. Fouille-le : la plume est à toi !"},final=false,tool="basket",kid=false},{k="pecheur",who="Zyno, le vieux pêcheur",x=180,y=401,src="assets/npc3/pecheur.png",mw=368,mh=255,head=4,feet=254,cx=201,sc=0.1824,id="toto",need={fish=2,crab=2},title="2 poissons et 2 crabes pour Zyno",start={"Ho ho, Myah ! Pour le grand repas de la fête, il me faut du poisson et des crabes ! Mais ces temps-ci, mes filets remontent presque vides… J'ai besoin de tes yeux de jeune pêcheuse !","Pêche 2 poissons avec ta canne (canne), depuis la plage : l'eau du lac est trop trouble en ce moment. Et attrape 2 crabes rouges avec ton panier (panier), sur le sable !","Je garde une plume de Gaïkin dans mon coffre. Des pirates la voulaient, mais je n'ai rien dit ! Toi, tu es de confiance."},remind={"Il me faut encore du poisson et des crabes pour le festin. Les poissons sont près de l'eau, les crabes sur le sable !"},done={"Quelle belle pêche, et quels beaux crabes ! Bravo Myah !","Avant, je remontais mes filets pleins. Moins de plumes dans l'eau, c'est moins de nourriture pour les poissons. Ma plume sera plus utile dans le lac que dans ma cale.","Mon coffre est caché dans la cale de mon bateau, devant le lit La plume t'attend !"},final=false,tool="fish",kid=false},{k="juliana",who="Yulia, la directrice du musée",x=745,y=95,src="assets/npc3/juliana.png",mw=318,mh=252,head=2,feet=252,cx=167,sc=0.17024,id="plume",need={mango=5,banana=6},title="La fête : 5 6",start={"Myah ! Au musée, on prépare le grand festin de la fête du Cygne !","Pour le festin, il me faut : 5 mangues et 6 bananes. Les manguiers près du musée et de l'escalier de l'observatoire, et les bananiers du jardin, en sont pleins !","Le dernier coffre est dans l'observatoire : Yurii le garde. Il contient un très vieux livre sur la légende de Gaïkin. Quand tu auras fini, va voir Yurii à l'observatoire !"},remind={"Pour le festin, il me faut : 5 mangues et 6 bananes !"},done={"Hourra ! Le festin sera délicieux !","Ce repas, c'est pour montrer à Gaïkin que toute l'île l'attend.","Le coffre est caché à l'intérieur de l'observatoire, derrière les plantes C'est le dernier coffre !"},locked={"Reviens me voir quand tu auras aidé Miraaï, Nijan, Lulia et Zyno ! Le dernier coffre vient à la fin."},final=true,kid=false},{k="maima",who="Maïmaï, la cheffe de l'île",x=660,y=351,src="assets/npc3/maima.png",mw=347,mh=253,head=3,feet=253,cx=181,sc=0.15808,final=false,lines={"Bonjour ma petite Myah ! Je suis Maïmaï, la cheffe de l'île.","Gaïkin, notre grand cygne, est parti depuis des années. Son lac devient trouble… je suis très inquiète.","Les habitants gardent ses plumes en secret. Aide-les, gagne leur confiance, et Gaïkin reviendra peut-être."},kid=false},{k="poggi",who="Poggi, l'ouvrier agricole",x=764,y=402,src="assets/npc3/poggi.png",mw=273,mh=252,head=1,feet=251,cx=121,sc=0.18848,final=false,lines={"Hé, Myah ! Je suis Poggi, l'ouvrier agricole : je récolte les fruits et les légumes de l'île, et je ramasse des noix de coco pour le festin.","Si tu cherches des noix de coco , des mangues ou des bananes , regarde près du bassin et du musée : les arbres refont des fruits au bout de 30 secondes !"},kid=false},{k="gardien",who="Yurii, l'ornithologue",x=767,y=95,src="assets/npc3/gardien.png",mw=144,mh=256,head=0,feet=256,cx=74,sc=0.19,final=false,lines={"Bonjour Myah ! Je suis Yurii, l'ornithologue : je suis les oiseaux de l'île depuis l'observatoire.","Depuis que Gaïkin est parti, je cherche son ombre dans le ciel chaque soir. Prends la longue-vue : tu verras peut-être quelque chose !"},kid=false},{k="kykah",who="Kykah, la marchande",x=468,y=423,src="assets/npc3/kykah.png",mw=346,mh=257,head=6,feet=256,cx=194,sc=0.17024,final=false,lines={"Bienvenue ! Perles, coquillages et colliers : tout vient de nos plages.","Pour la pêche, pense à ta canne (canne) : les poissons de la mer sont plus gros que ceux de l'étang !"},kid=false},{k="kahn",who="Kahn, ton papa, le poissonnier",x=322,y=378,src="assets/npc3/kahn.png",mw=323,mh=253,head=3,feet=253,cx=162,sc=0.18544,final=false,lines={"Ma puce ! Te voilà ! Aujourd'hui, on a du travail avec Zyno : les filets se remplissent vite sur la plage.","Tu veux bien m'aider à pêcher ? Je te réserve un trésor rare !"},kid=false},{k="kito",who="Kito, le bébé de la marchande",x=442,y=429,src="assets/npc3/kito.png",mw=312,mh=290,head=39,feet=289,cx=173,sc=0.06688,final=false,lines={"Gouuu ! Ba-ba !","Kito agite son petit perroquet rouge. Il ne quitte jamais sa maman."},kid=true},{k="lila",who="Lila, la fille de Kykah et de Poggi",x=398,y=437,src="assets/npc3/lila.png",mw=267,mh=266,head=15,feet=265,cx=139,sc=0.13376,final=false,lines={"Salut Myah ! Moi, c'est Lila. Maman vend des coquillages et papa récolte les fruits et les légumes de l'île.","Avec ma loupe et mon carnet, je cherche des indices partout sur l'île. Même mon perroquet m'aide !"},kid=true},{k="romi",who="Romi, le grand frère",x=520,y=397,src="assets/npc3/romi.png",mw=315,mh=252,head=2,feet=252,cx=163,sc=0.16720000000000002,final=false,lines={"Salut Myah. Moi, c'est Romi, le grand frère de Lila et de Kito.","Je glisse partout avec ma planche. Maman dit que j'écoute trop de musique, mais j'entends quand même tout."},kid=true}},houses={{id="home",name="La maison de Myah",door={188,197},exit={188,211},r=11,img="assets/interieur2.jpg",W=1375,H=768,K=3.5,floor={{135,585},{450,520},{772,462},{777,552},{940,474},{960,470},{1100,505},{1240,585},{1225,610},{1000,708},{700,748},{560,755},{400,742},{135,605}},sexit={715,740}},{id="care",name="Le Poste de Soin",door={350,243},exit={350,250},r=11,img="assets/soin2.jpg",W=896,H=1195,K=3.6,floor={{175,805},{230,745},{300,712},{440,700},{470,690},{620,770},{720,830},{745,860},{745,985},{700,1000},{560,1000},{440,1000},{300,950},{200,880}},sexit={715,975}},{id="hall",name="Le Comptoir de Maïmaï",door={430,188},exit={430,201},r=40,img="assets/mairie3.jpg",W=896,H=1195,K=3.6,floor={{165,810},{215,745},{290,700},{400,690},{470,685},{625,765},{725,825},{750,860},{750,990},{705,1005},{560,1005},{440,1005},{300,960},{190,890}},sexit={715,975}},{id="museum",name="Musée Kaïkiti",door={628,110},exit={616,126},r=11,img="assets/musee.jpg",W=768,H=1024,K=3.2,floor={{300,590},{500,590},{600,640},{640,700},{660,780},{620,830},{480,835},{452,845},{452,960},{345,960},{332,845},{300,835},{170,830},{140,780},{160,700},{200,640}},sexit={400,945}},{id="boat",name="Le Bateau",door={182,424},exit={164,422},r=8,img="assets/bateau.jpg",W=1200,H=896,K=5,floor={{255,600},{330,520},{480,420},{650,335},{800,245},{940,262},{1075,330},{1085,430},{960,560},{830,672},{640,765},{450,775},{310,715}},sexit={470,748}},{id="obs",name="L'Observatoire",door={760,82},exit={760,92},r=9,img="assets/observatoire.jpg",W=896,H=1200,K=4.4,floor={{50,885},{330,668},{600,672},{850,882},{600,1015},{300,1015}},sexit={450,1005}},{id="ukai",name="Maison Ukaï",door={530,292},exit={530,304},r=20,img="assets/ukai.jpg",W=1375,H=768,K=3.5,floor={{215,655},{300,600},{420,540},{540,528},{640,560},{722,572},{752,592},{800,606},{850,574},{1075,575},{1140,602},{1225,590},{1262,598},{1250,626},{1000,742},{800,756},{700,762},{560,735},{330,695},{225,672}},sexit={868,722}}},trees={{x=622,y=370,kind="banana"},{x=654,y=394,kind="banana"},{x=450,y=172,kind="coconut"},{x=508,y=173,kind="coconut"},{x=606,y=212,kind="mango"},{x=632,y=232,kind="mango"},{x=276,y=251,kind="coconut"},{x=586,y=392,kind="coconut"}},flowers={{622,366},{694,394},{654,394},{258,190}},perch={470,274},start={427,305},indoor={{quest="rose",house="home"},{quest="soleil",house="care"},{quest="plume",house="museum"}},NPC_K=0.76,MS=0.26}
